import backtrader as bt


class RiskOnRiskOffStrategy(bt.Strategy):
    def __init__(self):
        self.order = None
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=200)
        self.crossover = bt.indicators.CrossOver(self.data.close, self.sma)

    def next(self):
        if self.order:
            return

        if not self.position and self.crossover[0] > 0:
            self.order = self.order_target_percent(target=1.0)
        elif self.position and self.crossover[0] < 0:
            self.order = self.close()

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None
